package cn.zhuatech.contractai.controller; import cn.zhuatech.contractai.common.ApiResponse; import cn.zhuatech.contractai.dto.ContractAiDto.*; import cn.zhuatech.contractai.service.ContractAiService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('DOMAIN_OPERATOR','QUALITY','ADMIN')") public class OperationsAdminController {private final ContractAiService service;public OperationsAdminController(ContractAiService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<WorkRecordView>> orders(){return ApiResponse.ok(service.workRecords());}}
